CREATE TABLE public.himmah_days (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.narration_sessions(id), title text NOT NULL, day_date date NOT NULL, error_weight integer NOT NULL DEFAULT 4 CHECK(error_weight BETWEEN 1 AND 100), fail_threshold integer NOT NULL DEFAULT 12 CHECK(fail_threshold BETWEEN 1 AND 1000), ranking_mode text NOT NULL DEFAULT 'passed' CHECK(ranking_mode IN ('passed','completion')), registration_open boolean NOT NULL DEFAULT false, invite_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(32),'hex'), expires_at timestamptz NOT NULL DEFAULT now()+interval '48 hours', manager_name text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '', association_logo_url text NOT NULL DEFAULT '', stamp_url text NOT NULL DEFAULT '', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.himmah_days TO authenticated; GRANT ALL ON public.himmah_days TO service_role;
ALTER TABLE public.himmah_days ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.himmah_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day_id uuid NOT NULL REFERENCES public.himmah_days(id), student_id uuid NOT NULL REFERENCES public.students(id), halaqa_id uuid NOT NULL REFERENCES public.halaqat(id), student_name text NOT NULL, halaqa_name text NOT NULL, teacher_name text NOT NULL DEFAULT '', hizbs integer[] NOT NULL, present boolean NOT NULL DEFAULT false, UNIQUE(day_id,student_id));
GRANT SELECT ON public.himmah_participants TO authenticated; GRANT ALL ON public.himmah_participants TO service_role;
ALTER TABLE public.himmah_participants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.himmah_reviewers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day_id uuid NOT NULL REFERENCES public.himmah_days(id), full_name text NOT NULL, phone text NOT NULL DEFAULT '', user_id uuid, token_hash text UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(day_id,user_id));
GRANT SELECT ON public.himmah_reviewers TO authenticated; GRANT ALL ON public.himmah_reviewers TO service_role;
ALTER TABLE public.himmah_reviewers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.himmah_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), participant_id uuid NOT NULL REFERENCES public.himmah_participants(id), reviewer_id uuid NOT NULL REFERENCES public.himmah_reviewers(id), hizb integer NOT NULL CHECK(hizb BETWEEN 1 AND 60), attempt_no integer NOT NULL, request_id uuid NOT NULL UNIQUE, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, duration_seconds integer, mistakes integer NOT NULL DEFAULT 0 CHECK(mistakes BETWEEN 0 AND 10000), warnings integer NOT NULL DEFAULT 0 CHECK(warnings BETWEEN 0 AND 10000), error_weight integer, fail_threshold integer, equivalent_errors integer, status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','ended','pass','fail')), approved_at timestamptz, UNIQUE(participant_id,hizb,attempt_no));
CREATE UNIQUE INDEX himmah_one_running ON public.himmah_attempts(participant_id,hizb,reviewer_id) WHERE status IN ('running','ended');
GRANT SELECT ON public.himmah_attempts TO authenticated; GRANT ALL ON public.himmah_attempts TO service_role;
ALTER TABLE public.himmah_attempts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.himmah_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day_id uuid NOT NULL REFERENCES public.himmah_days(id), attempt_id uuid REFERENCES public.himmah_attempts(id), actor_id uuid, action text NOT NULL, previous_value jsonb, new_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.himmah_audit TO authenticated; GRANT ALL ON public.himmah_audit TO service_role;
ALTER TABLE public.himmah_audit ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.himmah_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) AND public.get_staff_role(auth.uid())='manager' $$;
CREATE FUNCTION public.himmah_view_halaqa(_halaqa uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) AND (public.get_staff_role(auth.uid()) IN ('manager','supervisor','assistant_supervisor','secretary','admin_staff') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.active AND (_halaqa=p.assigned_halaqa_id OR _halaqa=p.assigned_assistant_halaqa_id))) $$;
CREATE POLICY himmah_day_manager ON public.himmah_days FOR SELECT TO authenticated USING(public.himmah_admin());
CREATE POLICY himmah_participant_read ON public.himmah_participants FOR SELECT TO authenticated USING(public.himmah_view_halaqa(halaqa_id));
CREATE POLICY himmah_reviewer_manager ON public.himmah_reviewers FOR SELECT TO authenticated USING(public.himmah_admin());
CREATE POLICY himmah_attempt_read ON public.himmah_attempts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.himmah_participants p WHERE p.id=participant_id AND public.himmah_view_halaqa(p.halaqa_id)));
CREATE POLICY himmah_audit_manager ON public.himmah_audit FOR SELECT TO authenticated USING(public.himmah_admin());
CREATE FUNCTION public.himmah_register(_invite text,_name text,_phone text,_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.himmah_days; r uuid; BEGIN SELECT * INTO d FROM public.himmah_days WHERE invite_key=_invite AND registration_open AND expires_at>now() FOR UPDATE; IF d.id IS NULL THEN RAISE EXCEPTION 'الرابط غير متاح أو انتهت صلاحيته'; END IF; IF length(trim(_name)) NOT BETWEEN 3 AND 120 OR _phone !~ '^(05[0-9]{8}|9665[0-9]{8})$' OR _token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'الاسم أو الجوال غير صحيح'; END IF; IF EXISTS(SELECT 1 FROM public.himmah_reviewers WHERE day_id=d.id AND phone=_phone AND created_at>now()-interval '1 minute') OR (SELECT count(*) FROM public.himmah_reviewers WHERE day_id=d.id)>2000 THEN RAISE EXCEPTION 'يرجى الانتظار قبل إعادة التسجيل'; END IF; INSERT INTO public.himmah_reviewers(day_id,full_name,phone,token_hash) VALUES(d.id,trim(_name),_phone,encode(extensions.digest(_token,'sha256'),'hex')) RETURNING id INTO r; RETURN jsonb_build_object('day_id',d.id,'reviewer_id',r); END $$;
REVOKE ALL ON FUNCTION public.himmah_register(text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_register(text,text,text,text) TO anon,authenticated;
CREATE FUNCTION public.himmah_dashboard(_day uuid,_token text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.himmah_days; ext boolean:=false; rid uuid; result jsonb; BEGIN SELECT * INTO d FROM public.himmah_days WHERE id=_day; IF d.id IS NULL THEN RAISE EXCEPTION 'اليوم غير موجود'; END IF; IF _token IS NOT NULL THEN SELECT id INTO rid FROM public.himmah_reviewers WHERE day_id=_day AND active AND token_hash=encode(extensions.digest(_token,'sha256'),'hex'); ext:=rid IS NOT NULL AND d.expires_at>now(); IF NOT ext THEN RAISE EXCEPTION 'انتهت جلسة الوصول'; END IF; ELSIF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'غير مصرح'; END IF;
SELECT jsonb_build_object('day', (to_jsonb(d)-'invite_key'-'created_by') || CASE WHEN public.himmah_admin() AND NOT ext THEN jsonb_build_object('invite_key',d.invite_key) ELSE '{}'::jsonb END,'can_manage',public.himmah_admin() AND NOT ext,'reviewer_id',rid,'participants',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.student_name) FROM public.himmah_participants p WHERE p.day_id=_day AND (ext OR public.himmah_view_halaqa(p.halaqa_id))),'[]'::jsonb),'reviewers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'full_name',r.full_name,'active',r.active,'phone',CASE WHEN public.himmah_admin() AND NOT ext THEN r.phone ELSE '' END)) FROM public.himmah_reviewers r WHERE r.day_id=_day),'[]'::jsonb),'attempts',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.started_at) FROM public.himmah_attempts a JOIN public.himmah_participants p ON p.id=a.participant_id WHERE p.day_id=_day AND (ext OR public.himmah_view_halaqa(p.halaqa_id))),'[]'::jsonb),'audit',CASE WHEN public.himmah_admin() AND NOT ext THEN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM public.himmah_audit WHERE day_id=_day ORDER BY created_at DESC LIMIT 100) x),'[]'::jsonb) ELSE '[]'::jsonb END) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.himmah_dashboard(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_dashboard(uuid,text) TO anon,authenticated;
CREATE FUNCTION public.himmah_day_list() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'غير مصرح'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'title',d.title,'day_date',d.day_date) ORDER BY d.day_date DESC) FROM public.himmah_days d WHERE public.himmah_admin() OR EXISTS(SELECT 1 FROM public.himmah_participants p WHERE p.day_id=d.id AND public.himmah_view_halaqa(p.halaqa_id))),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.himmah_day_list() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_day_list() TO authenticated;
CREATE FUNCTION public.himmah_manage(_action text,_day uuid DEFAULT NULL,_data jsonb DEFAULT '{}'::jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; did uuid:=_day; s public.students; h public.halaqat; hs integer[]; BEGIN IF NOT public.himmah_admin() THEN RAISE EXCEPTION 'الإعداد للإدارة فقط'; END IF;
IF _action='create' THEN IF length(trim(_data->>'title')) NOT BETWEEN 3 AND 150 THEN RAISE EXCEPTION 'اسم اليوم مطلوب'; END IF; INSERT INTO public.narration_sessions(title,session_date,created_by) VALUES(_data->>'title',(_data->>'day_date')::date,auth.uid()) RETURNING id INTO sid; INSERT INTO public.himmah_days(session_id,title,day_date,created_by) VALUES(sid,_data->>'title',(_data->>'day_date')::date,auth.uid()) RETURNING id INTO did;
ELSIF _action='participant' THEN SELECT * INTO s FROM public.students WHERE id=(_data->>'student_id')::uuid; SELECT * INTO h FROM public.halaqat WHERE id=s.halaqa_id; SELECT array_agg(DISTINCT x ORDER BY x) INTO hs FROM jsonb_array_elements_text(_data->'hizbs') v, LATERAL (SELECT v.value::integer x) n; IF s.id IS NULL OR h.id IS NULL OR cardinality(hs)<1 OR cardinality(hs)>60 OR EXISTS(SELECT 1 FROM unnest(hs) x WHERE x<1 OR x>60) THEN RAISE EXCEPTION 'اختر الطالب والأحزاب من 1 إلى 60'; END IF; IF EXISTS(SELECT 1 FROM public.himmah_attempts a JOIN public.himmah_participants p ON p.id=a.participant_id WHERE p.day_id=did AND p.student_id=s.id AND NOT a.hizb=ANY(hs)) THEN RAISE EXCEPTION 'لا يمكن إزالة حزب له محاولات مسجلة'; END IF; INSERT INTO public.himmah_participants(day_id,student_id,halaqa_id,student_name,halaqa_name,teacher_name,hizbs) VALUES(did,s.id,h.id,s.full_name,h.name,coalesce((SELECT full_name FROM public.profiles WHERE id=h.teacher_id),''),hs) ON CONFLICT(day_id,student_id) DO UPDATE SET hizbs=excluded.hizbs;
ELSIF _action='attendance' THEN UPDATE public.himmah_participants SET present=(_data->>'present')::boolean WHERE id=(_data->>'participant_id')::uuid AND day_id=did;
ELSIF _action='revoke' THEN UPDATE public.himmah_reviewers SET active=false WHERE id=(_data->>'reviewer_id')::uuid AND day_id=did;
ELSIF _action='settings' THEN UPDATE public.himmah_days SET error_weight=(_data->>'error_weight')::integer,fail_threshold=(_data->>'fail_threshold')::integer,ranking_mode=_data->>'ranking_mode',registration_open=(_data->>'registration_open')::boolean,expires_at=(_data->>'expires_at')::timestamptz,manager_name=left(coalesce(_data->>'manager_name',''),120),logo_url=coalesce(_data->>'logo_url',''),association_logo_url=coalesce(_data->>'association_logo_url',''),stamp_url=coalesce(_data->>'stamp_url','') WHERE id=did;
ELSIF _action='correct' THEN RAISE EXCEPTION 'استخدم محاولة جديدة؛ النتائج المعتمدة محفوظة دون استبدال'; ELSE RAISE EXCEPTION 'عملية غير صحيحة'; END IF;
INSERT INTO public.himmah_audit(day_id,actor_id,action,new_value) VALUES(did,auth.uid(),_action,_data); RETURN did; END $$;
REVOKE ALL ON FUNCTION public.himmah_manage(text,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_manage(text,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.himmah_attempt(_action text,_day uuid,_participant uuid DEFAULT NULL,_hizb integer DEFAULT NULL,_attempt uuid DEFAULT NULL,_request uuid DEFAULT NULL,_mistakes integer DEFAULT 0,_warnings integer DEFAULT 0,_token text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.himmah_days; p public.himmah_participants; r public.himmah_reviewers; a public.himmah_attempts; n integer; BEGIN SELECT * INTO d FROM public.himmah_days WHERE id=_day FOR SHARE; IF d.id IS NULL THEN RAISE EXCEPTION 'اليوم غير موجود'; END IF;
IF _token IS NOT NULL THEN SELECT * INTO r FROM public.himmah_reviewers WHERE day_id=_day AND active AND token_hash=encode(extensions.digest(_token,'sha256'),'hex'); IF r.id IS NULL OR d.expires_at<=now() THEN RAISE EXCEPTION 'انتهت جلسة الوصول'; END IF;
ELSE IF NOT public.is_staff(auth.uid()) OR public.get_staff_role(auth.uid()) NOT IN ('manager','teacher','assistant_teacher') THEN RAISE EXCEPTION 'غير مصرح بإدخال النتائج'; END IF; INSERT INTO public.himmah_reviewers(day_id,full_name,user_id) SELECT _day,full_name,id FROM public.profiles WHERE id=auth.uid() ON CONFLICT(day_id,user_id) DO NOTHING; SELECT * INTO r FROM public.himmah_reviewers WHERE day_id=_day AND user_id=auth.uid() AND active; IF r.id IS NULL THEN RAISE EXCEPTION 'جلسة موقوفة'; END IF; END IF;
IF _action='start' THEN SELECT * INTO p FROM public.himmah_participants WHERE id=_participant AND day_id=_day FOR UPDATE; ELSE SELECT * INTO a FROM public.himmah_attempts WHERE id=_attempt FOR UPDATE; SELECT * INTO p FROM public.himmah_participants WHERE id=a.participant_id AND day_id=_day; IF a.reviewer_id IS DISTINCT FROM r.id THEN RAISE EXCEPTION 'لا يمكنك تعديل محاولة مسمّع آخر'; END IF; END IF;
IF p.id IS NULL OR (_token IS NULL AND NOT public.himmah_view_halaqa(p.halaqa_id)) THEN RAISE EXCEPTION 'الطالب خارج نطاقك'; END IF;
IF _mistakes NOT BETWEEN 0 AND 10000 OR _warnings NOT BETWEEN 0 AND 10000 OR _mistakes IS NULL OR _warnings IS NULL THEN RAISE EXCEPTION 'الأعداد يجب أن تكون صحيحة وغير سالبة'; END IF;
IF _action='start' THEN IF _request IS NULL OR _hizb IS NULL OR NOT _hizb=ANY(p.hizbs) THEN RAISE EXCEPTION 'الحزب غير مقرر'; END IF; SELECT * INTO a FROM public.himmah_attempts WHERE request_id=_request; IF a.id IS NOT NULL THEN IF a.reviewer_id<>r.id OR a.participant_id<>p.id OR a.hizb<>_hizb THEN RAISE EXCEPTION 'طلب مكرر غير صحيح'; END IF; RETURN to_jsonb(a); END IF; SELECT * INTO a FROM public.himmah_attempts WHERE participant_id=p.id AND hizb=_hizb AND reviewer_id=r.id AND status IN ('running','ended'); IF a.id IS NOT NULL THEN RETURN to_jsonb(a); END IF; SELECT coalesce(max(attempt_no),0)+1 INTO n FROM public.himmah_attempts WHERE participant_id=p.id AND hizb=_hizb; INSERT INTO public.himmah_attempts(participant_id,reviewer_id,hizb,attempt_no,request_id) VALUES(p.id,r.id,_hizb,n,_request) RETURNING * INTO a;
ELSIF _action IN ('counts','end') THEN IF a.status NOT IN ('running','ended') THEN RAISE EXCEPTION 'النتيجة معتمدة؛ ابدأ محاولة جديدة'; END IF; UPDATE public.himmah_attempts SET mistakes=_mistakes,warnings=_warnings,ended_at=CASE WHEN _action='end' THEN coalesce(ended_at,clock_timestamp()) ELSE ended_at END,duration_seconds=CASE WHEN _action='end' THEN coalesce(duration_seconds,greatest(0,floor(extract(epoch FROM clock_timestamp()-started_at))::integer)) ELSE duration_seconds END,status=CASE WHEN _action='end' THEN 'ended' ELSE status END WHERE id=a.id RETURNING * INTO a;
ELSIF _action='approve' THEN IF a.status IN ('pass','fail') THEN RETURN to_jsonb(a); END IF; IF a.status<>'ended' THEN RAISE EXCEPTION 'أنهِ الحزب قبل الاعتماد'; END IF; UPDATE public.himmah_attempts SET error_weight=d.error_weight,fail_threshold=d.fail_threshold,equivalent_errors=mistakes*d.error_weight+warnings,status=CASE WHEN mistakes*d.error_weight+warnings>=d.fail_threshold THEN 'fail' ELSE 'pass' END,approved_at=clock_timestamp() WHERE id=a.id RETURNING * INTO a; UPDATE public.himmah_participants SET present=true WHERE id=p.id; INSERT INTO public.himmah_audit(day_id,attempt_id,actor_id,action,new_value) VALUES(_day,a.id,r.id,'approve',to_jsonb(a)); ELSE RAISE EXCEPTION 'عملية غير صحيحة'; END IF; RETURN to_jsonb(a); END $$;
REVOKE ALL ON FUNCTION public.himmah_attempt(text,uuid,uuid,integer,uuid,uuid,integer,integer,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_attempt(text,uuid,uuid,integer,uuid,uuid,integer,integer,text) TO anon,authenticated;
REVOKE ALL ON FUNCTION public.himmah_admin(),public.himmah_view_halaqa(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.himmah_admin(),public.himmah_view_halaqa(uuid) TO authenticated;
